?>
<section id="<?php echo esc_attr($sectionId);?>" class="pricing-matrix px-6 <?php echo esc_attr(inkwell_component_section_classes($settings,$p));?>"><div class="mx-auto <?php echo esc_attr(inkwell_component_container_class($settings,$p));?>"><header class="mb-8 max-w-3xl"><?php if($eyebrow){?><p class="mb-3 text-xs font-semibold uppercase tracking-[.14em] opacity-60"><?php echo esc_html($eyebrow);?></p><?php }?><?php if($title){?><h2 class="text-[clamp(32px,4vw,48px)] font-semibold leading-tight"><?php echo esc_html($title);?></h2><?php }?><?php if($intro){?><p class="mt-3 leading-7 opacity-70"><?php echo wp_kses_post($intro);?></p><?php }?></header><?php if($packages){?><div class="overflow-x-auto rounded border border-[#dfe5ee]"><table class="w-full min-w-[760px] border-collapse bg-white text-[#09152f]"><caption class="sr-only"><?php echo esc_html($title?:'Package comparison');?></caption><thead><tr><th class="sticky left-0 z-20 w-[220px] border-b border-r border-[#dfe5ee] bg-white p-4 text-left text-sm" scope="col">Feature</th><?php foreach($packages as $package){?><th class="relative min-w-[180px] border-b border-[#dfe5ee] p-5 text-center" scope="col"><?php if(!empty($package["{$p}_recommended"])){?><span class="absolute inset-x-0 -top-px bg-[#0867f2] py-1 text-[10px] font-semibold uppercase tracking-wider text-white">Most popular</span><?php }?><strong class="block <?php echo !empty($package["{$p}_recommended"])?'pt-4':'';?>"><?php echo esc_html($package["{$p}_package_name"]??'');?></strong><?php if(!empty($package["{$p}_package_subtitle"])){?><span class="mt-1 block text-xs font-normal text-[#68758d]"><?php echo esc_html($package["{$p}_package_subtitle"]);?></span><?php }?></th><?php }?></tr></thead><tbody><?php foreach($features as $feature){$values=$feature["{$p}_values"]??[];?><tr><th class="sticky left-0 z-10 border-b border-r border-[#e5eaf1] bg-white p-4 text-left text-sm font-medium" scope="row"><?php echo esc_html($feature["{$p}_feature_name"]??'');?></th><?php foreach($packages as $i=>$package){$value=$values[$i]["{$p}_feature_value"]??'—';?><td class="border-b border-[#e5eaf1] p-4 text-center text-sm <?php echo !empty($package["{$p}_recommended"])?'bg-[#f5f9ff]':'';?>"><?php echo esc_html($value);?></td><?php }?></tr><?php }?><tr><th class="sticky left-0 z-10 border-r border-[#dfe5ee] bg-white p-4 text-left text-sm font-semibold" scope="row">Price</th><?php foreach($packages as $package){?><td class="p-5 text-center <?php echo !empty($package["{$p}_recommended"])?'bg-[#f5f9ff]':'';?>"><strong><?php echo esc_html($package["{$p}_package_price"]??'');?></strong><?php if(!empty($package["{$p}_price_suffix"])){?><span class="ml-1 text-xs text-[#68758d]"><?php echo esc_html($package["{$p}_price_suffix"]);?></span><?php }?></td><?php }?></tr><tr><th class="sticky left-0 z-10 border-r border-[#dfe5ee] bg-white p-4"><span class="sr-only">Actions</span></th><?php foreach($packages as $package){?><td class="p-5 text-center <?php echo !empty($package["{$p}_recommended"])?'bg-[#f5f9ff]':'';?>"><?php echo inkwell_component_link($package["{$p}_package_cta"]??null,!empty($package["{$p}_recommended"])?'inline-flex rounded bg-[#0867f2] px-6 py-3 text-sm font-semibold text-white':'inline-flex rounded border border-[#0867f2] px-6 py-3 text-sm font-semibold text-[#0867f2]');?></td><?php }?></tr></tbody></table></div><?php }?></div></section>
